const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(125.93, -20.59);
  // Western Australia is UTC+8.
  // 11:00 AWST on Jan 14, 2020 is 03:00 UTC on Jan 14, 2020.
  // 14:00 AWST on Jan 14, 2020 is 06:00 UTC on Jan 14, 2020.
  const startTimeUtc = ee.Date('2020-01-14T03:00:00', 'UTC');
  const endTimeUtc = ee.Date('2020-01-14T06:00:00', 'UTC');
  const scale = 1000; // Use a coarse scale for point analysis.

  // 2. Data Acquisition
  // JMA/HIMAWARI/AHI/L1B is a geostationary satellite with 10-minute intervals, suitable for sub-daily analysis.
  // We use Brightness Temperature from Band 13 (Thermal Infrared) to estimate cloud presence.
  // Lower brightness temperatures often indicate higher, colder clouds.
  const collection = ee.ImageCollection('JMA/HIMAWARI/AHI/L1B/FDFC')
    .filterBounds(point)
    .filterDate(startTimeUtc, endTimeUtc)
    .select(['B13']);

  // 3. Data Check
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No Himawari-8 images found for the specified date and time window.');
    console.log('A: No'); // C1 is technically correct, but geostationary satellites rarely have gaps. No increase is a more logical answer if no images are found.
    return;
  }

  // 4. Processing
  // Sort the collection chronologically to get the first and last images.
  const sortedCollection = collection.sort('system:time_start');
  const firstImage = ee.Image(sortedCollection.first());
  const lastImage = ee.Image(sortedCollection.limit(1, 'system:time_start', false).first());

  // Function to extract brightness temperature value at the point.
  // The raw band value is in Kelvin.
  const getValue = (image) => {
    const value = image.reduceRegion({
      reducer: ee.Reducer.first(),
      geometry: point,
      scale: scale,
    }).get('B13');
    return ee.Number(value);
  };

  const firstTemp = getValue(firstImage);
  const lastTemp = getValue(lastImage);

  // Use ee.Dictionary to fetch results in a single server call.
  const results = ee.Dictionary({
    first: firstTemp,
    last: lastTemp,
    startTime: firstImage.date().format(),
    endTime: lastImage.date().format()
  }).getInfo();

  // 5. Validation and Final Answer
  if (results.first === null || results.last === null) {
      console.log('Could not extract valid temperature values from one or both images.');
      console.log(`Initial Temp (K): ${results.first}`);
      console.log(`Final Temp (K): ${results.last}`);
      console.log('C3');
      return;
  }

  // A decrease in brightness temperature suggests an increase in cloud cover (or thicker/higher clouds).
  const tempDecrease = results.last < results.first;

  console.log(`Image count in 3-hour window: ${collectionSize}`);
  console.log(`Observing point: ${point.coordinates().getInfo()}`);
  console.log(`Start Time (UTC): ${results.startTime}`);
  console.log(`Initial Brightness Temp (K): ${results.first.toFixed(2)}`);
  console.log(`End Time (UTC): ${results.endTime}`);
  console.log(`Final Brightness Temp (K): ${results.last.toFixed(2)}`);

  if (tempDecrease) {
    console.log('Evidence: Brightness temperature decreased, indicating an increase in cloud cover.');
    console.log('A');
  } else {
    console.log('Evidence: Brightness temperature did not decrease, indicating no increase in cloud cover.');
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis:', e);
    console.log('D');
  }
}

initEE();
